                onPress={zoomIn}
                size="icon"
                variant="ghost"
                disabled={zoomLevel >= ZOOM_MAX}
              >
                <Icon as={PlusIcon} className="size-5" />
              </Button>
              <Button onPress={toggleColorScheme} size="icon" variant="ghost">
                <Icon
                  as={colorScheme === 'dark' ? SunIcon : MoonStarIcon}
                  className="size-5"
                />
              </Button>
            </View>
          ),
        }}
      />
      <View className="flex-1 bg-background">
        <TimelineView />
        <BottomBar />
      </View>
    </>
  );
}

