            </View>
            {/* Grid line */}
            <View className="flex-1 border-t border-border" />
          </View>
        ))}

        {/* Entry blocks */}
        {entries.map((entry) => {
          const status = statuses.find((s) => s.id === entry.statusId);
          return (
            <TimelineEntryBlock
              key={entry.id}
              entry={entry}
              status={status}
              hourHeight={hourHeight}
            />
          );
        })}

        {/* Current time line */}
        <CurrentTimeLine hourHeight={hourHeight} />
      </View>
    </ScrollView>
  );
}

